-- The Photography style of the business page (decided 22 Nov 2026: Tikka focuses its pilot on two
-- niches, beauty and photography; photographers pick the new Photography category and get a
-- gallery-first page automatically).
--
-- 1. business_page.style: null follows the category (Photography → 'photography', anything else
--    → 'beauty'); the owner can pick one under "More options". Only the look changes: services,
--    booking, deposits, drops and reviews are the same on both.
-- 2. Each portfolio photo can carry its shape (width, height), its main colour (tone) and its
--    camera settings (camera, lens, aperture, shutter, iso), read in the owner's browser from the
--    original file before it's shrunk (the WebP copy keeps none of it). All optional: photos
--    uploaded before this have none, and the page measures them as they load.
-- 3. Photographers' own ready-made offers (docs/drop-templates.md, category `photography`).

alter table public.business_page
  add column style text check (style in ('beauty', 'photography'));
grant update (style) on public.business_page to authenticated;

alter table public.business_portfolio
  add column width int check (width between 1 and 20000),
  add column height int check (height between 1 and 20000),
  add column tone text check (tone ~ '^#[0-9a-f]{6}$'),
  add column camera jsonb check (camera is null or (jsonb_typeof(camera) = 'object' and length(camera::text) <= 300)),
  add constraint business_portfolio_size check ((width is null) = (height is null));

alter table public.drop_templates drop constraint drop_templates_category_check;
alter table public.drop_templates add constraint drop_templates_category_check
  check (category in ('beauty_hair', 'photography', 'spa_wellness', 'fitness', 'food_drinks', 'fashion', 'health_clinics', 'education', 'other_services'));

